$ErrorActionPreference = 'Stop'
$root = (Get-Location).Path
$engine = Join-Path $root 'KMC.Engine\Navigation\MoonPeriapsisOptimizer.cs'
$project = Join-Path $root 'KMC.Engine\KMC.Engine.csproj'
$tests = Join-Path $root 'Tools\NavigationTests\Program.cs'
$marker = '        Run("moon finite-SOI entry and periapsis diagnostics", MoonEncounterFoundation);'
$methodAnchor = '    private static void SchematicAngleSelectionRegression()'
$compileAnchor = '    <Compile Include="Navigation\MoonEncounterEvaluator.cs" />'
foreach ($f in @($project, $tests)) { if (!(Test-Path $f)) { throw "Missing $f" } }
$p = [IO.File]::ReadAllText($project)
$t = [IO.File]::ReadAllText($tests)
if (!( $p.Contains($compileAnchor) -and $t.Contains($marker) -and $t.Contains($methodAnchor) )) { throw 'Expected frozen 14.24.2 anchors missing. No changes made.' }
if ($p.Contains('MoonPeriapsisOptimizer.cs') -or $t.Contains('MoonPeriapsisCorrectionRegression') -or (Test-Path $engine)) { throw '14.24.3 already present or partially applied; inspect before retry.' }
$backup = Join-Path $env:TEMP ('KMC_14_24_3_backup_' + (Get-Date -Format yyyyMMdd_HHmmss))
New-Item -ItemType Directory -Path $backup | Out-Null
Copy-Item $project (Join-Path $backup 'KMC.Engine.csproj')
Copy-Item $tests (Join-Path $backup 'Program.cs')
$source = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String(''))
$method = [Text.Encoding]::UTF8.GetString([Convert]::FromBase64String(''))
try {
  [IO.File]::WriteAllText($engine, $source, (New-Object Text.UTF8Encoding($false)))
  $p = $p.Replace($compileAnchor, $compileAnchor + "`r`n" + '    <Compile Include="Navigation\MoonPeriapsisOptimizer.cs" />')
  [IO.File]::WriteAllText($project, $p, (New-Object Text.UTF8Encoding($false)))
  $t = $t.Replace($marker, $marker + "`r`n" + '        Run("moon 3D periapsis correction preserves SOI feasibility", MoonPeriapsisCorrectionRegression);')
  $t = $t.Replace($methodAnchor, $method + $methodAnchor)
  [IO.File]::WriteAllText($tests, $t, (New-Object Text.UTF8Encoding($false)))
} catch {
  Copy-Item (Join-Path $backup 'KMC.Engine.csproj') $project -Force
  Copy-Item (Join-Path $backup 'Program.cs') $tests -Force
  if (Test-Path $engine) { Remove-Item $engine -Force }
  throw
}
Write-Host 'KMC 14.24.3 experimental moon periapsis optimizer applied.'
Write-Host "Backup: $backup"
Write-Host 'No KSP Plugin/Shared DLL replacement required. Run NavigationTests.'
